"""invsqrt_ph: turn the results of invsqrt_ph_netsearch.py into the data module tools/invsqrt_ph_net.py and check
the networks symbolically for every exponent (own code, workstream invsqrt_ph).
usage: invsqrt_ph_mknet.py <fwd log of netsearch | fwd json of netsat> <bwd json of netsat or -> <out .py>"""
import json
import pprint
import sys

HEAD = '''"""invsqrt_ph: swap network of the normaliser, found by tools/invsqrt_ph_netsearch.py (own search; this file
is generated by tools/invsqrt_ph_mknet.py). A pair is [wire a, wire b, exponents for which the swap is on,
exponents for which it must be off]; all other exponents are don't-cares.
FWD: %d swaps (data bits only; the leading one is cleared before). UNNORM runs FWD in reverse order.
BWD: network for UNNORM on the half thermometer (%s), found by tools/invsqrt_ph_netsat.py: a layer is a set
of swaps under ONE control alpha[e >> 1] xor beta (e & 1); the leading one goes from wire 21 to wire e.
"""
'''


def last_net(path):
    net = None
    for line in open(path):
        if line.startswith("NET "):
            net = json.loads(line[4:])
    assert net is not None, path
    return net


def check(net):
    fwd = net["dir"] == "fwd"
    for e in range(22):
        s = 21 - e
        if fwd:
            pos = {i: i for i in range(e)}
            want = {i: i + s for i in range(e)}
        else:
            pos = {i: i + s for i in range(e)}
            want = {i: i for i in range(e)}
            pos["lead"], want["lead"] = 21, e
        for layer in net["layers"]:
            for a, b, on, off in layer["pairs"]:
                occ = [k for k, q in pos.items() if q in (a, b)]
                if e in on:
                    for k in occ:
                        pos[k] = b if pos[k] == a else a
                else:
                    assert not occ or e in off, (e, a, b)      # an occupied pair that is not on must be off
        assert pos == want, (e, pos, want)
    return sum(len(l["pairs"]) for l in net["layers"])


def from_sat_fwd(raw):
    """Forward network written by invsqrt_ph_netsat.py (mode fwd: every swap with its own list of exponents)
    in the format of this file: [wire a, wire b, on, off]; `off` = exponents for which one of the two wires
    holds a data bit while the swap is not on (found by following the bits)."""
    layers = []
    pos = {e: {i: i for i in range(e)} for e in range(22)}
    for lay in raw["layers"]:
        pairs = []
        for (a, b), on in zip(lay["pairs"], lay["on"]):
            off = []
            for e in range(22):
                occ = [k for k, q in pos[e].items() if q in (a, b)]
                if e in on:
                    for k in occ:
                        pos[e][k] = b if pos[e][k] == a else a
                elif occ:
                    off.append(e)
            pairs.append([a, b, [e for e in on if True], off])
        layers.append({"spec": lay["spec"], "pairs": pairs})
    return {"dir": "fwd", "specs": raw["specs"], "layers": layers}


def check_layers(net):
    """Network with one control per layer (output of invsqrt_ph_netsat.py, mode bwd): every bit of every
    exponent must go from wire s + i to wire i, the leading one from wire 21 to wire e."""
    for e in range(22):
        s = 21 - e
        pos = {i: i + s for i in range(e)}
        want = {i: i for i in range(e)}
        lin = net.get("lead_in")
        by_and = (e >> 1) in net.get("lead_and", [])          # leading one set by one AND after the swaps
        if by_and:
            lin = None
        elif lin is not None:                                 # the leading one enters at [layer index, wire]
            want["lead"] = e
        else:
            pos["lead"], want["lead"] = 21, e
        for li, layer in enumerate(net["layers"] + [None]):
            if lin is not None and lin[e >> 1][0] == li:
                assert lin[e >> 1][1] not in pos.values(), ("leading one enters on a used wire", e)
                pos["lead"] = lin[e >> 1][1]
            if layer is None:
                break
            if layer["alpha"][e >> 1] ^ (layer["beta"] & e & 1):
                at = {q: k for k, q in pos.items()}
                assert len(at) == len(pos)
                for a, b in layer["pairs"]:
                    ka, kb = at.get(a), at.get(b)
                    if ka is not None:
                        pos[ka] = b
                    if kb is not None:
                        pos[kb] = a
        assert pos == want, (e, pos, want)
    return sum(len(l["pairs"]) for l in net["layers"])


def main():
    if sys.argv[1].endswith(".json"):
        fwd = from_sat_fwd(json.load(open(sys.argv[1])))        # written by invsqrt_ph_netsat.py fwd out=...
    else:
        fwd = last_net(sys.argv[1])
    nf = check(fwd)
    bwd, nb = None, 0
    if sys.argv[2] != "-":
        raw = json.load(open(sys.argv[2]))                    # written by invsqrt_ph_netsat.py out=...
        layers, first = [], []                              # first[l] = index of the first layer made of solver layer l
        for l in (raw["all_layers"] if raw.get("lead_in") else raw["layers"]):
            l = dict(l, pairs=[list(pr) for pr in l["pairs"]])
            first.append(len(layers))
            if isinstance(l["beta"], list):                   # mode bws: one control per swap; swaps of a solver
                for pr, al, be in zip(l["pairs"], l["alpha"], l["beta"]):      # layer are disjoint
                    if layers and layers[-1].get("_src") is l and (layers[-1]["alpha"], layers[-1]["beta"]) == (al, be):
                        layers[-1]["pairs"].append(pr)
                    else:
                        layers.append({"alpha": al, "beta": be, "pairs": [pr], "_src": l})
            else:
                layers.append({"alpha": l["alpha"], "beta": l["beta"], "pairs": l["pairs"]})
        for l in layers:
            l.pop("_src", None)
        lead_and = raw.get("lead_and", [])
        first.append(len(layers))
        bwd = {"dir": "bwd", "swaps": sum(len(l["pairs"]) for l in layers), "specs": raw["specs"], "layers": layers,
               "lead_and": lead_and}                          # e >> 1 whose leading one is set by an AND
        if raw.get("lead_in"):                                # [index of the layer before which it enters, wire]
            bwd["lead_in"] = [[first[l], q] for l, q in raw["lead_in"]]
        nb = check_layers(bwd)
    with open(sys.argv[3], "w") as fh:
        fh.write(HEAD % (nf, "%d swaps" % nb if bwd else "none stored"))
        fh.write("FWD = " + pprint.pformat(fwd, width=118, compact=True) + "\n\n")
        fh.write("BWD = " + pprint.pformat(bwd, width=118, compact=True) + "\n")
    print("fwd swaps", nf, "bwd swaps", nb, "leading ones by AND for e >> 1 in", bwd["lead_and"] if bwd else None)


if __name__ == "__main__":
    main()
